package it.andreademartini.trading.paper.patternv1;
import static it.andreademartini.trading.paper.patternv1.PatternPaperModel.*;
import static it.andreademartini.trading.paper.patternv1.PatternPaperTestSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;

class PatternPaperLedgerTest {
    @Test void commissionBeforeExecutionIsPersistedAndAppliedOnce(){var s=ledgerSession();var fee=new CommissionRecord("early",bd(1.5),"USD",Instant.now());assertTrue(PatternPaperLedger.commission(s,fee));assertFalse(PatternPaperLedger.commission(s,fee));assertEquals(1,s.pendingCommissions.size());assertEquals(0,PatternPaperLedger.capital(s,Instant.now()).equity().compareTo(bd(10000)));PatternPaperLedger.execution(s,fill(s,"early",100,10,100));assertTrue(s.pendingCommissions.isEmpty());assertEquals(0,s.trades.getFirst().commission.compareTo(bd(1.5)));assertFalse(PatternPaperLedger.commission(s,fee));assertEquals(0,PatternPaperLedger.capital(s,Instant.now()).equity().compareTo(bd(9998.5)));}
    @Test void executionReplayIsIdempotent(){var s=ledgerSession();var fill=fill(s,"execution-1",100,5,100);assertTrue(PatternPaperLedger.execution(s,fill));assertFalse(PatternPaperLedger.execution(s,fill));assertEquals(1,s.executions.size());assertEquals(0,s.trades.getFirst().entered.compareTo(bd(5)));}
    @Test void actualPartialFillsAreWeightedAndCommissionIsAppliedOnce(){var s=ledgerSession();PatternPaperLedger.execution(s,fill(s,"a",100,4,100));PatternPaperLedger.execution(s,fill(s,"b",100,6,101));assertEquals(0,s.trades.getFirst().entryPrice().compareTo(bd(100.6)));var fee=new CommissionRecord("a",bd(1),"USD",Instant.now());assertTrue(PatternPaperLedger.commission(s,fee));assertFalse(PatternPaperLedger.commission(s,fee));assertEquals(0,s.trades.getFirst().commission.compareTo(bd(1)));}
    @Test void actualStopAndTargetPricesDeterminePnl(){var s=ledgerSession();s.orders.getFirst().status="Filled";PatternPaperLedger.execution(s,fill(s,"entry",100,10,100.2));PatternPaperLedger.execution(s,fill(s,"exit",102,10,105.8));PatternPaperLedger.commission(s,new CommissionRecord("entry",bd(1),"USD",Instant.now()));PatternPaperLedger.commission(s,new CommissionRecord("exit",bd(1),"USD",Instant.now()));assertTrue(s.trades.getFirst().closed());assertEquals("TARGET",s.trades.getFirst().exitReason);assertEquals(0,s.trades.getFirst().netPnl().compareTo(bd(54)));assertEquals(0,PatternPaperLedger.capital(s,Instant.now()).equity().compareTo(bd(10054)));}
    @Test void liveOrOtherAccountExecutionIsRejected(){var s=ledgerSession();var fill=fill(s,"a",100,1,100);var live=new ExecutionRecord(fill.executionId(),null,100,1000,"U_LIVE","AAPL","BUY",bd(1),bd(100),fill.time(),null);assertThrows(IllegalStateException.class,()->PatternPaperLedger.execution(s,live));assertTrue(s.executions.isEmpty());}
    @Test void overfillAndUnknownOrderAreRejected(){var s=ledgerSession();assertThrows(IllegalStateException.class,()->PatternPaperLedger.execution(s,fill(s,"a",100,11,100)));var f=new ExecutionRecord("x",null,999,999,ACCOUNT,"AAPL","BUY",bd(1),bd(100),Instant.now(),null);assertThrows(IllegalStateException.class,()->PatternPaperLedger.execution(s,f));}
    @Test void virtualEquityRemainsTenThousandBeforeFills(){var s=ledgerSession();assertEquals(0,PatternPaperLedger.capital(s,Instant.now()).equity().compareTo(bd(10000)));assertEquals(0,PatternPaperLedger.capital(s,Instant.now()).committed().compareTo(bd(1001.3)));}
    @Test void commissionCorrectionUpdatesDeltaAndNonUsdCannotBeInvented(){var s=ledgerSession();PatternPaperLedger.execution(s,fill(s,"a",100,10,100));PatternPaperLedger.commission(s,new CommissionRecord("a",bd(1),"USD",Instant.now()));PatternPaperLedger.commission(s,new CommissionRecord("a",bd(1.2),"USD",Instant.now()));assertEquals(0,s.trades.getFirst().commission.compareTo(bd(1.2)));assertThrows(IllegalStateException.class,()->PatternPaperLedger.commission(s,new CommissionRecord("a",bd(1),"EUR",Instant.now())));}
}
